1	// SPDX-License-Identifier: MIT
2	pragma solidity 0.8.24;
3	
4	import {IERC20} from "../interfaces/IERC20.sol";
5	import {IRewardDistributor} from "../interfaces/IRewardDistributor.sol";
6	import {SafeTransferLib} from "../libraries/SafeTransferLib.sol";
7	import {FixedPointMath} from "../libraries/FixedPointMath.sol";
8	import {Ownable2Step} from "../auth/Ownable2Step.sol";
9	import {FeeController} from "./FeeController.sol";
10	import {WithdrawalQueue} from "./WithdrawalQueue.sol";
11	
12	/// @title StakingVault
13	/// @notice Single-asset staking vault issuing non-transferable shares.
14	/// @dev Exits are two-phase: {requestWithdrawal} burns shares and books the
15	///      asset amount into the queue, {completeWithdrawal} pays out once the
16	///      cooldown has elapsed.
17	///
18	///      Total assets are tracked in storage rather than read from the token
19	///      balance, so an unsolicited transfer into this contract cannot move the
20	///      share price.
21	///
22	///      Invariants:
23	///        - totalSupply == 0  <=>  totalAssets == 0.
24	///        - Shares are non-transferable; balanceOf only changes on deposit and
25	///          on withdrawal request.
26	///        - The reward distributor is checkpointed for an account before that
27	///          account's share balance changes.
28	contract StakingVault is Ownable2Step {
29	    using SafeTransferLib for IERC20;
30	    using FixedPointMath for uint256;
31	
32	    /// @notice The staked asset.
33	    IERC20 public immutable asset;
34	
35	    /// @notice Fee policy for exits.
36	    FeeController public immutable feeController;
37	
38	    /// @notice Exit bookkeeping.
39	    WithdrawalQueue public immutable withdrawalQueue;
40	
41	    /// @notice Reward accounting. Set once, after deployment.
42	    IRewardDistributor public rewardDistributor;
43	
44	    /// @notice Account permitted to pause deposits alongside the owner.
45	    address public guardian;
46	
47	    /// @notice When true, new deposits and yield accrual are rejected.
48	    bool public paused;
49	
50	    /// @notice Total shares outstanding.
51	    uint256 public totalSupply;
52	
53	    /// @notice Shares held per account. Non-transferable.
54	    mapping(address => uint256) public balanceOf;
55	
56	    /// @notice Assets under management, tracked in storage.
57	    uint256 public totalAssets;
58	
59	    uint256 private _entered;
60	
61	    error Reentrancy();
62	    error Paused();
63	    error NotGuardian();
64	    error ZeroAmount();
65	    error ZeroShares();
66	    error DistributorAlreadySet();
67	    error InsufficientShares(uint256 held, uint256 requested);
68	
69	    event Deposited(address indexed account, uint256 assets, uint256 shares);
70	    event WithdrawalRequested(address indexed account, uint256 indexed id, uint256 shares, uint256 assets);
71	    event WithdrawalCompleted(address indexed account, uint256 indexed id, uint256 assets, uint256 fee);
72	    event YieldAccrued(uint256 assets);
73	    event PausedSet(bool paused);
74	    event GuardianUpdated(address indexed oldGuardian, address indexed newGuardian);
75	    event RewardDistributorSet(address indexed distributor);
76	
77	    modifier nonReentrant() {
78	        if (_entered == 1) revert Reentrancy();
79	        _entered = 1;
80	        _;
81	        _entered = 0;
82	    }
83	
84	    modifier whenNotPaused() {
85	        if (paused) revert Paused();
86	        _;
87	    }
88	
89	    constructor(
90	        IERC20 asset_,
91	        address initialOwner,
92	        address initialGuardian,
93	        FeeController feeController_,
94	        uint64 cooldown_
95	    ) Ownable2Step(initialOwner) {
96	        require(address(asset_) != address(0), "ASSET_ZERO");
97	        require(address(feeController_) != address(0), "FEES_ZERO");
98	        asset = asset_;
99	        feeController = feeController_;
100	        guardian = initialGuardian;
101	        withdrawalQueue = new WithdrawalQueue(address(this), cooldown_);
102	    }
103	
104	    // ---------------------------------------------------------------- views
105	
106	    /// @notice Shares that `assets` would mint at the current exchange rate.
107	    function convertToShares(uint256 assets) public view returns (uint256) {
108	        uint256 supply = totalSupply;
109	        if (supply == 0) return assets;
110	        return assets.mulDiv(supply, totalAssets);
111	    }
112	
113	    /// @notice Assets that `shares` are currently worth.
114	    function convertToAssets(uint256 shares) public view returns (uint256) {
115	        uint256 supply = totalSupply;
116	        if (supply == 0) return shares;
117	        return shares.mulDiv(totalAssets, supply);
118	    }
119	
120	    // ------------------------------------------------------------ user flow
121	
122	    /// @notice Stake `assets` and receive shares.
123	    /// @dev Rounds shares down, which favours the vault over the depositor.
124	    function deposit(uint256 assets) external nonReentrant whenNotPaused returns (uint256 shares) {
125	        if (assets == 0) revert ZeroAmount();
126	
127	        _checkpoint(msg.sender);
128	
129	        shares = convertToShares(assets);
130	        if (shares == 0) revert ZeroShares();
131	
132	        totalAssets += assets;
133	        totalSupply += shares;
134	        balanceOf[msg.sender] += shares;
135	
136	        asset.safeTransferFrom(msg.sender, address(this), assets);
137	
138	        emit Deposited(msg.sender, assets, shares);
139	    }
140	
141	    /// @notice Burn `shares` and open a cooldown before the assets can be taken.
142	    /// @dev Deliberately callable while paused so a pause cannot trap funds.
143	    function requestWithdrawal(uint256 shares) external nonReentrant returns (uint256 id) {
144	        if (shares == 0) revert ZeroAmount();
145	
146	        uint256 held = balanceOf[msg.sender];
147	        if (held < shares) revert InsufficientShares(held, shares);
148	
149	        _checkpoint(msg.sender);
150	
151	        uint256 assets = convertToAssets(shares);
152	
153	        balanceOf[msg.sender] = held - shares;
154	        totalSupply -= shares;
155	        totalAssets -= assets;
156	
157	        // The fee in force now is held for this request, so a later fee change
158	        // cannot be applied retroactively to an exit already in the cooldown.
159	        id = withdrawalQueue.enqueue(msg.sender, assets, feeController.withdrawalFeeBps());
160	
161	        emit WithdrawalRequested(msg.sender, id, shares, assets);
162	    }
163	
164	    /// @notice Collect a matured withdrawal request, net of the exit fee.
165	    /// @dev The fee applied is the one quoted when the request was made.
166	    function completeWithdrawal(uint256 id) external nonReentrant returns (uint256 paid) {
167	        (uint256 assets, uint256 feeBps) = withdrawalQueue.settle(id, msg.sender);
168	
169	        uint256 fee = assets.mulDiv(feeBps, feeController.BPS_DENOMINATOR());
170	        paid = assets - fee;
171	
172	        if (fee != 0) {
173	            asset.safeTransfer(feeController.feeRecipient(), fee);
174	        }
175	        asset.safeTransfer(msg.sender, paid);
176	
177	        emit WithdrawalCompleted(msg.sender, id, paid, fee);
178	    }
179	
180	    // ----------------------------------------------------------- privileged
181	
182	    /// @notice Push external yield into the vault, raising the share price.
183	    function accrueYield(uint256 assets) external onlyOwner nonReentrant whenNotPaused {
184	        if (assets == 0) revert ZeroAmount();
185	        require(totalSupply != 0, "NO_SUPPLY");
186	
187	        totalAssets += assets;
188	        asset.safeTransferFrom(msg.sender, address(this), assets);
189	
190	        emit YieldAccrued(assets);
191	    }
192	
193	    /// @notice Wire up reward accounting. Callable once.
194	    function setRewardDistributor(IRewardDistributor distributor) external onlyOwner {
195	        if (address(rewardDistributor) != address(0)) revert DistributorAlreadySet();
196	        require(address(distributor) != address(0), "DISTRIBUTOR_ZERO");
197	        rewardDistributor = distributor;
198	        emit RewardDistributorSet(address(distributor));
199	    }
200	
201	    function setGuardian(address newGuardian) external onlyOwner {
202	        emit GuardianUpdated(guardian, newGuardian);
203	        guardian = newGuardian;
204	    }
205	
206	    /// @notice Halt deposits. Withdrawals are unaffected.
207	    function pause() external {
208	        if (msg.sender != owner && msg.sender != guardian) revert NotGuardian();
209	        paused = true;
210	        emit PausedSet(true);
211	    }
212	
213	    /// @notice Resume deposits.
214	    function unpause() external onlyOwner {
215	        paused = false;
216	        emit PausedSet(false);
217	    }
218	
219	    // ------------------------------------------------------------- internal
220	
221	    /// @dev Settle reward accounting for `account` at its pre-change balance.
222	    function _checkpoint(address account) private {
223	        IRewardDistributor distributor = rewardDistributor;
224	        if (address(distributor) != address(0)) {
225	            distributor.checkpoint(account);
226	        }
227	    }
228	}
229

